dtsPropsFor.Container:
children: React.ReactNode;
/** Extra classes merged onto the centred max-w-content (1100px) wrapper. */
className?: string;

dtsPropsFor.Section:
/** Anchor id; the h2 gets `${id}-heading`. */
id: string;
/** Small-caps orange label above the heading. */
label: string;
heading?: React.ReactNode;
/** Optional side panel (usually a DataPanel), floated right of the prose from md up. */
panel?: React.ReactNode;
/** Hairline rule above the section. Default true. */
divider?: boolean;
/** Drop the 720px prose measure (for card grids). Default false. */
wide?: boolean;
children: React.ReactNode;

dtsPropsFor.DataPanel:
/** Small-caps panel title. */
label: string;
rows: { label: string; value: string }[];

dtsPropsFor.PostCard:
post: {
  slug: string;
  title: string;
  description: string;
  /** ISO date, rendered as e.g. "12 March 2026". */
  date: string;
  tags: string[];
  /** e.g. "6 min". */
  readingTime?: string;
};

dtsPropsFor.EarlyAccessForm:
/** Ground the form sits on. Default "light". */
theme?: "light" | "dark";
/** Analytics source tag sent with the submission. */
source?: string;
/** Default "Talk to Us". */
buttonLabel?: string;
className?: string;
/** Overrides the default confirmation line. */
successMessage?: string;
/** Guide download revealed on success. */
download?: { href: string; label: string };
/** "email" (default): one email field + button. "full": name, company, optional role and work email. */
fields?: "email" | "full";
